import { Badge } from '@/components'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils'
import { ChevronRight } from 'lucide-react-native'
import { Text, TouchableOpacity, View } from 'react-native'
import { humanizeCredits } from '../utils/format'
import { OrganizationPlan } from '@/generated/graphql'
import { capitalize } from 'lodash'
import { router } from 'expo-router'
import { CreditsProgressBar } from './CreditsProgressBar'

type CreditUsageProps = {
	plan: OrganizationPlan
	balance: bigint
	planCredits: bigint
	subscriptionStartDate: string | null
	canUseMax: boolean
}

export const CreditUsage = ({
	plan,
	balance,
	planCredits,
	subscriptionStartDate,
	canUseMax
}: CreditUsageProps) => {
	const { theme } = useTheme()

	const openCreditsDetail = () => {
		router.push({
			pathname: '/profile/credits-detail',
			params: {
				balance: balance.toString(),
				planCredits: planCredits.toString()
			}
		})
	}

	return (
		<TouchableOpacity
			style={styles.container(theme)}
			onPress={openCreditsDetail}
		>
			<View style={styles.creditUsageHeader}>
				<View style={styles.creditUsageInfoText}>
					<Text style={styles.creditsUsedText(theme)}>
						{humanizeCredits(balance)}{' '}
					</Text>
					<Text style={styles.creditsTotalText(theme)}>
						/ {humanizeCredits(planCredits)} credits left
					</Text>
				</View>
				<ChevronRight size={20} color={colors[theme].gray[900]} />
			</View>

			<View>
				<CreditsProgressBar
					progress={1 - Number(balance) / Number(planCredits)}
				/>
			</View>

			<View style={styles.creditUsageFooter}>
				<Text style={styles.currentPlanText(theme)}>Current Plan:</Text>
				<Badge color="gray">
					{plan.toLowerCase().startsWith('pro') && canUseMax
						? 'Max'
						: capitalize(plan.split('_')[0])}
				</Badge>
			</View>
		</TouchableOpacity>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		borderRadius: 20,
		padding: 16,
		gap: 16,
		backgroundColor: colors[theme].gray[50]
	}),
	creditUsageHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center'
	},
	creditUsageInfoText: {
		flexDirection: 'row',
		alignItems: 'flex-end'
	},
	creditsUsedText: (theme: Theme) => ({
		fontSize: 22,
		fontWeight: '600',
		color: colors[theme].gray[900]
	}),
	creditsTotalText: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[900],
		marginBottom: 2
	}),
	creditUsageFooter: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between'
	},
	currentPlanText: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[400]
	})
})
